package br.com.nuvemtv;
import org.json.*;import java.util.*;
/** Até 100 mensagens por conversa, só em memória; uma resposta tardia não apaga um envio aceito. */
final class ChatHistory {
 static String now(){java.text.SimpleDateFormat format=new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'",Locale.US);format.setTimeZone(TimeZone.getTimeZone("UTC"));return format.format(new Date());}
 static final int LIMIT=100;final Map<String,JSONObject> messages=new LinkedHashMap<>();String continuation="";boolean loaded;
 static JSONArray array(JSONObject response)throws Exception{JSONArray a=response.optJSONArray("messages");JSONObject c=response.optJSONObject("conversation");if(a==null&&c!=null)a=c.optJSONArray("messages");if(a==null&&(response.has("conversationId")||c!=null))return new JSONArray();if(a==null)throw new Exception("Formato de mensagens não reconhecido");return a;}
 static String text(JSONObject raw){if(raw.optBoolean("isDeleted"))return "";JSONArray parts=raw.optJSONArray("parts");JSONObject payload=raw.optJSONObject("contentPayload"),content=payload==null?raw.optJSONObject("content"):payload.optJSONObject("content");if(parts==null&&content!=null)parts=content.optJSONArray("parts");StringBuilder s=new StringBuilder();if(parts!=null)for(int i=0;i<Math.min(50,parts.length());i++){JSONObject p=parts.optJSONObject(i);if(p!=null&&"text".equalsIgnoreCase(p.optString("contentType"))){if(s.length()>0)s.append('\n');String value=p.optString("text");s.append(value,0,Math.min(4096,value.length()));if(s.length()>=8192)break;}}return s.toString();}
 static String key(JSONObject message){String id=message.optString("messageId");return id.isEmpty()?message.optString("sender",message.optString("senderXuid"))+"|"+message.optString("timestamp")+"|"+text(message):id;}
 void accepted(JSONObject response,String content){JSONObject item=Json.obj("messageId",response.optString("messageId","local-"+UUID.randomUUID()),"sender","","timestamp",now(),"localAccepted",true,"parts",Json.arr(Json.obj("contentType","text","text",content)));messages.put(key(item),item);trim();}
 void merge(JSONObject response,boolean older)throws Exception{JSONArray source=array(response);for(int i=0;i<Math.min(100,source.length());i++){JSONObject raw=source.optJSONObject(i);if(raw!=null)messages.put(key(raw),raw);}JSONObject nested=response.optJSONObject("conversation");String next=response.optString("continuationToken",nested==null?"":nested.optString("continuationToken"));if(older||!loaded)continuation=next;loaded=true;trim();}
 List<JSONObject> ordered(){List<JSONObject> list=new ArrayList<>(messages.values());list.sort(Comparator.comparing(m->m.optString("timestamp")));return list;}
 void trim(){List<JSONObject> list=ordered();for(int i=0;i<list.size()-LIMIT;i++)messages.remove(key(list.get(i)));if(messages.size()>=LIMIT)continuation="";}
 String render(String other,String me,String waiting,String empty){StringBuilder out=new StringBuilder();for(JSONObject item:ordered()){String value=text(item);if(value.isEmpty())continue;String sender=item.optString("sender",item.optString("senderXuid"));out.append(sender.isEmpty()||item.optBoolean("localAccepted")?me:sender.equals(targetXuid)?other:me).append(" · ").append(item.optString("timestamp").replace('T',' ').replace("Z"," UTC")).append('\n').append(value);if(item.optBoolean("localAccepted"))out.append("\n").append(waiting);out.append("\n\n");}return out.length()==0?empty:out.toString();}
 String targetXuid="";
}
